"""Human-authored v0.0.4 screen/state catalogue; generates planning data, not runtime UI."""
import json
from pathlib import Path
screens=[]
def add(i,title,kind,entry,lines,actions,rule,edge):
 screens.append(dict(id=f'S{i:02}',title=title,kind=kind,entry=entry,lines=lines.split('|'),actions=[dict(label=a,target=b) for a,b in actions],rule=rule,edge=edge))
add(1,'실행 · Splash / 저장 확인','splash','Steam에서 실행 또는 재실행','CURSOR HUNTER|저장 데이터를 확인하고 있습니다|첫 실행이면 언어와 표시 설정으로 이동',[('첫 실행','S02'),('저장 정상','S04'),('저장 손상','S03'),('버전 불일치','S48')],'최소0.8초. 실제 초기화 완료 전 건너뛰기 불가. 로컬 읽기를 우선하며 Steam 미연결은 오프라인 안내로 분기.','로딩은10초부터 지연 안내,30초 뒤 재시도/종료. 기존 저장을 새 게임으로 덮어쓰지 않는다.')
add(2,'첫 실행 · 언어 / 표시 / 안내','setup','S01에서 유효한 진행 저장이 없는 경우','언어: 한국어 / English|창 모드 1920 x 1080 / UI 100%|화면 흔들림 OFF / 조작 안내 ON',[('시작하기','S04'),('표시 설정','S35')],'기본 언어를 선택하고 수동으로 바꿀 수 있다. 첫 설정 저장 후 Main으로 이동한다. 기본 설정만으로 시작할 수 있다.','화면이 작으면1280x720에 맞춘다. 시작 버튼은 저장 완료까지 중복 입력 잠금.')
add(3,'저장 손상 · 백업 복구','modal','S01 로컬 진행 파일 읽기/검증 실패','진행 데이터를 읽을 수 없습니다|백업: 09/09 10:20 / 보스 v2 / 28분|원본을 보존하고 백업을 복구합니다',[('백업 복구','S44'),('다시 읽기','S01'),('종료','S41')],'백업 시간·보스·플레이 시간을 함께 표시. 유효한 백업만 복구 가능. 새 게임은 데이터 설정의 별도 확인에서만 허용.','백업도 손상되면 복구 비활성,오류코드와 로그 위치 제공. 닫기/ESC로 새 게임 진입 금지.')
add(4,'Main · 새 게임 / 이어서 사냥','main','첫 설정 완료, 정상 저장 로드, 정산의 Main','CURSOR HUNTER|보스 v2 격파 / 다음 목표 v3|일반 Field / 보스 / 특성 / 설정',[('일반 Field','S05'),('보스 선택','S20'),('특성','S12'),('설정','S34'),('기록','S42'),('게임 종료','S41')],'첫 일반 진입만S05, 이후S07. Main에는 몬스터·타이머·보상 없음. 메뉴Fade0.25초→HUD0.2초 후 런 시작.','진행 저장1개. 메뉴의 이어서 사냥은 새60초 런이지 중단 전투 재개가 아니다.')
add(5,'첫 사냥 안내 1 · 겹치고 클릭','tutorial','최초 일반 Field 진입 또는 설정에서 연습 다시 보기','커서를 슬라임 위에 겹쳐 주세요|왼쪽 버튼을 누르면 공격합니다|이동하거나 누르고 있는 것만으로는 공격하지 않습니다',[('처치 완료','S06'),('안내 건너뛰기','S07')],'연습 슬라임1체 HP20. 최초 조준·첫 클릭·첫 처치를 각각 강조. 연습에서는 시간 정지, 실재화 지급 없음.','두 번 클릭이 어려우면 커서 원을 강조. 건너뛰어도 도움말에서 재연습 가능, 반복 연습 보상 없음.')
add(6,'첫 사냥 안내 2 · 보석 / 제한 시간','tutorial-gem','S05 연습 몬스터 처치','처치하면 가넷이 우측 상단으로 이동합니다|일반 Field는 60초, 종료 시 획득량을 정산합니다|보스 처치 후 새 젬스톤 슬롯이 추가됩니다',[('60초 사냥 시작','S07'),('특성 살펴보기','S12')],'가넷 이동 방향을 화살표로 보여주고 보유/이번 판 수량을 구분. 연습 완료를 저장한 후 실제 런 시작. 잠긴 젬스톤은 표시하지 않는다.','특성으로 먼저 이동해도 일반 진입 시 연습을 반복하지 않는다. 초기 보유 가넷0.')
add(7,'일반 Field · 초반 직접 클릭','normal','Main 또는 일반 정산의 일반 시작','TIME 00:42|가넷 보유96 / 이번 판 +24|슬라임 8마리 처치 / 자동: 미해금',[('ESC 일시정지','S09'),('시간 종료','S45')],'커서 반경18px부터 시작. 해금 종별 주기에 따라 무리를 랜덤 생성. 유효한 겹침 대상 모두에 클릭 피해.','타이머0 이후 생성·피해 금지. 보석 이동이 끝나지 않아도 사망 기록을 정산한다.')
add(8,'일반 Field · 후반 중첩 물량','normal-late','v4 이후 일반 Field의 동일 화면 상태','TIME 00:12|해금 젬스톤5종 / 이번 판 가넷 +7,240만|자동 ON [A] / 30묶음 x 3타',[('자동 OFF 예시','S07'),('일시정지','S09'),('시간 종료','S45')],'슬라임부터 와이번까지 계속 중첩. 커서 반경240px, 넓은 링과 분산 파편으로 무리가 터지는 피드백. 수치는 화면 표현 예시.','자동 OFF는 같은 런·같은 능력 유지. 숫자·보석 연출을 묶어도 논리 처치 수는 보존.')
add(9,'일시정지 · 포커스 상실','modal','ESC, 창 포커스 상실, Steam Overlay 열기','일시정지|전투·스킬·파훼·타이머가 멈췄습니다|계속할 준비가 되면 다시 시작하세요',[('계속','S07'),('설정','S34'),('이번 판 종료','S10')],'계속은 원래 일반/보스와 남은 시간을 복원한다. 자동 재개하지 않는다.','종료 처리 중에는 새 일시정지를 열지 않는다. 포커스 복귀 클릭이 공격으로 전달되지 않게 한다.')
add(10,'중도 종료 확인 · 일반 / 보스','modal','S09 이번 판 종료','이번 사냥을 종료할까요?|일반: 지금까지 처치한 보상 지급|보스: 처치 실패로 모든 보상 미지급',[('계속 사냥','S09'),('일반 종료','S45'),('보스 포기','S30')],'현재 Field에 맞는 문구와 종료 버튼 하나만 실제 노출. 타이머는 확인 중 정지.','ESC는 취소. 종료 버튼 연타에도 결과 확정1회. 보스의 예약 보너스도 폐기.')
add(11,'일반 정산 · 즉시 다음 사냥','result','시간 종료 또는 일반 중도 종료의 저장 완료','일반 Field 완료 / 60초|가넷96 / 최종 지급96|실측 DPS10.7 / 슬라임32마리 / 지난 판 대비 +12%',[('다시 사냥 [Space]','S07'),('특성','S12'),('보스','S20'),('Main','S04')],'해금된 젬스톤만 종류별 기본/최종 수량으로 표시한다. 종별 처치, 전투 시간, 직전 런 대비 변화도 함께 보여준다.','Space는 저장 성공 이후 키를 새로 누를 때만 작동. 여러 판 자동 연속 시작은 없음. 목록4행 초과는 내부 스크롤.')
add(12,'Stat · 자유 분기 트리','stat','Main/정산/특성 다른 탭','Stat / Skill / Monster|공격력 · 범위 · 다중 타격 · 자동화|현재 해금된 젬스톤만 좌측 중단에 표시',[('Skill','S13'),('Monster','S14'),('노드 선택','S16'),('현재 특성','S15'),('사냥하기','S07')],'좌상단 탭, 좌측 중단 해금 젬스톤, 우상단 요약 고정. 중앙 트리만 팬·줌. 공격력30개 노드는 후반 부분 강화를 내부 횟수로 표시.','가지 간 선행 없음. 자동은v3만 요구, 더블/트리플 미구매여도 가능. 노드 드래그6px 이상이면 선택으로 처리하지 않는다.')
add(13,'Skill · 독립 스킬 가지','skill','특성 Skill 탭','파이어 볼 / 라이트닝 / 프리징|허리케인 / 드래곤 브레스|각 스킬 구매 -> 해당 스킬 피해 강화',[('Stat','S12'),('Monster','S14'),('해금 선택','S16'),('잠금 예시','S17'),('사냥하기','S07')],'스킬 간 구매 순서는 독립. 보스 배지만 순차 해금. 구매한 모든 스킬은 자동 장착. 강화는해당스킬 구매만 선행.','직전 스킬 미구매로 뒤 스킬을 잠그지 않는다. 보스 표식은 자동 스킬로 파훼하지 않는다.')
add(14,'Monster · 종별 두 갈래 강화','monster','특성 Monster 탭','슬라임 / 고블린 / 오크 / 골렘 / 와이번 / 드래곤|종 해금 -> 출현 강화 또는 보상 강화|해금한 모든 종은 계속 함께 출현',[('Stat','S12'),('Skill','S13'),('출현 강화 선택','S16'),('재화 부족 예시','S18'),('사냥하기','S07')],'출현과 보상 강화는 각각0~3, 서로 선행 없음. 종 해금도 다른 종 구입과 독립. 아이콘/이름/등급으로 종 구분.','전체 상한·생성 주기·배율을 상세에 보여주고 출현 강화가 적체를 늘릴 수 있음을 명시. 해금 종을 끄는 기능 없음.')
add(15,'현재 특성 · 그래프 상세','summary','우측 상단 요약 그래프 선택','공격력100 / L10 · 부분 강화0/10|반경60px / 2타격 / 자동 미구매|이론 DPS400 / 장착 스킬1 / 해금 몬스터2',[('Stat로 돌아가기','S12'),('Skill 보기','S13'),('Monster 보기','S14')],'공격L/30·반경레벨/6·타격M/3·자동F/30 고정 기준 막대. 실제 수치와 분리하며 총점화하지 않는다.','이론DPS=A×M×F, 수동F2·스킬 제외·100%명중. 실측DPS와 혼동하지 않게 별도 라벨.')
add(16,'구매 가능 · 노드 상세 / 첫 강화 안내','node','조건·재화가 충족된 노드를 선택','트리플 클릭 / 현재2타 -> 다음3타|필요: 가넷5,000 + 토파즈25|보유: 가넷50,000 + 토파즈85',[('1회 구매','S19'),('다른 가지 보기','S12'),('부족 상태 보기','S18')],'하단 상세에서만 구매. 첫 강화 때 선택→효과비교→구매→사냥 순서로3개 툴팁. 공격 부분 강화는 진척+즉시 피해량을 표시.','가격은 클릭 순간 다시 확인한다. 연타 중복 차감 금지. 저장 실패 시S40으로 이동하며 성공 효과는 저장 뒤 재생한다.')
add(17,'노드 잠금 · 선행 / 보스 조건','node-locked','아직 열리지 않은 노드 선택','자동 클릭: v3 오크 워로드 처치 필요|다른 Stat 가지의 구매는 필요하지 않습니다|비용: 가넷100만 + 자수정30',[('보스 선택','S20'),('다른 가지','S12')],'잠긴 이유를 한 문장으로 명시. 같은 가지 미구매라면 선행 노드로 이동 버튼. 먼 후반도 실루엣과 조건 미리 보기 가능.','회색만으로 구분하지 않고 자물쇠·요구 조건 노출. 비활성 구매버튼은 클릭/Enter를 처리하지 않는다.')
add(18,'재화 부족 · 부족량 / 획득처','node-poor','구매 조건은 충족했지만 보석이 부족','트리플 클릭 구매 불가|토파즈 보유10 / 필요25 / 부족15|획득처: 고블린, v1·v2 보스',[('일반 사냥','S07'),('보스 선택','S20'),('다른 가지','S12')],'필요 재화별 부족량을 표시하고 현재 해금된 획득처를 우선 안내한다. 잠긴 젬스톤은 보스 최초 처치 후 표시한다.','실제 보유 재화는 차감하지 않는다. 충분한 가지는 계속 구매 가능하며 젬스톤 간 대납은 없다.')
add(19,'구매 완료 · 부분 강화 / MAX','node-done','S16의 원자적 저장 성공','트리플 클릭 구매 완료 / 2타 -> 3타|가넷45,000 / 토파즈60|이 노드 MAX / 다른 가지도 성장 가능',[('다른 가지','S12'),('바로 사냥','S07'),('특성 요약','S15')],'0.25초 노드 발광과 짧은 상승음, 그래프 즉시 갱신. 반복 노드는 다음 효과·비용으로 바뀌고 MAX만 비활성.','구매 이전/이후 상태를 한번에 저장. 실패 시이전잔액·레벨 유지. 버튼을 누른 채로 다음 구매 자동 발생 금지.')
add(20,'보스 선택 · 도전 가능','boss-select','Main/정산의 보스 선택','v2 고블린 족장 / HP12,000 / 60초|파훼: 표식2개를 순서대로 클릭 / 실패 -4초|보상: 가넷2,000 + 토파즈35 / 추가 보상은 해금 후 표시',[('도전','S22'),('잠긴 보스 보기','S21'),('특성','S12'),('Main','S04')],'v1~v5 세로 목록, 현재HP/패턴미리보기/현재 해금 보상/최초해금/현재DPS. 다음 젬스톤 보상은 잠긴 보상으로 표시한다.','입장료 없음. 처치한 보스 반복 가능. 다음 보스는 직전 처치만 요구한다.')
add(21,'보스 선택 · 잠금','boss-locked','선행 보스를 처치하지 않은 행 선택','v3 오크 워로드 / 잠김|먼저 v2 고블린 족장을 처치하세요|해금 예정: 자동 클릭, 골렘, 프리징, 새 젬스톤',[('v2 선택','S20'),('특성','S12')],'보스의 이름·기본 패턴·해금 예정 항목을 보여준다. 보상 젬스톤은 이름 대신 잠긴 보상으로 표시하며 도전 버튼은 잠금 상태.','기준 레벨과 선행 보스 미처치를 분리해 표시한다.')
add(22,'보스 입장 · 준비','boss-intro','도전 클릭 후0.3초 Fade','고블린 족장|클릭으로 공격 / 숫자 표식을 순서대로 클릭|준비 0.6초 / 타이머는 아직 시작하지 않습니다',[('전투 시작','S23')],'소개0.6초 후60초 시작. 최초 보스만 파훼 도움말 추가, 반복입장은 간결하게.','준비 입력은 피해를 주지 않는다. 포커스 상실 시준비를정지하고 복귀 확인 후 진행.')
add(23,'보스 전투 · 기본 공격','boss','보스 소개 종료','v2 고블린 족장 HP8,400 / 12,000|TIME00:43 / 파훼 보너스 예약5%|일반 몬스터 없음 / 기본 공격은 일반과 동일',[('예고 발생','S24'),('처치 성공','S28'),('시간 초과','S30'),('일시정지','S09')],'HP는상단두번째행전폭, 타이머좌상단, 보석우상단. 보스 중앙 단독. 남은 HP와실측피해를 수치로 제공.','기본 공격 UI는 표식보다 낮은 입력 우선순위. 스킬은보스에게피해를 주지만 파훼는 하지 않는다.')
add(24,'보스 파훼 · 예고','boss-warning','각 보스별 정해진 경과 시각','고블린 족장이 공격을 준비합니다|예고0.6초 -> 입력창2.0초|번호가 켜지면 순서대로 클릭하세요',[('입력 창 열림','S25'),('일시정지','S09')],'보스 외곽에 표식윤곽만 보이고 예고 중 클릭은해결로 인정하지 않는다. 보스HP무적 없음.','첫예고는 도움말 한줄, 반복시짧은음과윤곽만. 빨간색만으로 상태를 구분하지 않는다.')
add(25,'보스 파훼 · 입력 진행','boss-input','예고 종료 후입력 창','표식1 완료 / 표식2 남음|남은 입력 시간1.2초|기본 공격·자동 클릭은 표식을 해결하지 않습니다',[('정답 클릭','S26'),('입력 시간 초과','S27'),('일시정지','S09')],'표식32px 반경, 숫자순서, 남은시간링. 잘못된 클릭은 진행없음·짧은 흔들림, 이벤트당실패1회.','직접좌클릭만 유효. 표식클릭이뒤보스피해로전달되지않는다. 보스가 먼저 죽으면 이벤트취소.')
add(26,'파훼 성공 · 보너스 예약','boss-good','모든 표식을 시간 내 정확히 클릭','파훼 성공! 처치 시 보상 +5%|현재 예약 보너스 +10% / 최대25%|시간 연장·추가 피해 없음',[('전투 계속','S23')],'0.5초표식파편·짧은확인음후HUD예약량갱신. 타이머계속. 모달을열지않는다.','보스처치성공에서만지급. 성공직후타임아웃이면예약량도0. 보너스종류별내림.')
add(27,'파훼 실패 · 시간 차감','boss-bad','입력 창 종료 시미완료','파훼 실패 / -4초|TIME00:25 -> 00:21|예약 보너스는 유지되지만 처치해야 지급',[('전투 계속','S23'),('차감으로 시간0','S30')],'붉은숫자·마이너스표시0.5초, 순간화면전체점멸 없음. 남은시간은0아래로내리지않음.','차감으로0이면즉시종료. 같은이벤트를중복실패로기록하지않고 파훼주기도앞당기지않는다.')
add(28,'보스 성공 정산 · 첫 처치 / 반복','boss-result','HP0→0.6초처치연출→저장완료','v2 고블린 족장 격파 / 40초|가넷2,000 +200 =2,200 / 토파즈35+3=38|자수정20+2=22 / 새 슬롯: 자수정 / DPS300 / 파훼2회',[('첫 처치 해금 보기','S29'),('일반 사냥','S07'),('보스 선택','S20'),('Main','S04')],'예시는보너스10%. 최초 처치 저장이 끝나면 자수정 슬롯을 추가하고 새 수량을 표시한다. 반복처치는해금안내버튼을숨긴다. v5최초면엔딩보기버튼으로전환한다.','저장후결과이동허용. 움직이는보석연출과 관계없이 사망 시점의 수량을 지급한다. 처치·보상·해금은동일정산ID.')
add(29,'최초 해금 · 다음 성장 안내','unlock','보스 첫 성공 정산','트리플 클릭 / 오크 / 라이트닝 / 자수정 슬롯 해금|지금 특성에서 원하는 가지를 구매할 수 있습니다|해금은 구매 자격이며 자동 구매가 아닙니다',[('특성으로','S12'),('일반 사냥','S07'),('다음 보스','S20')],'신규 노드·몬스터·스킬과 새 젬스톤 슬롯을 함께 표시한다. 한번 읽으면 NEW만 제거하고 해금 데이터는 유지한다.','v5표시는드래곤·브레스·L30이며엔딩을먼저볼수있다. 안내를 닫아도 보상은 다시 지급하지 않는다.')
add(30,'보스 실패 정산 · 성장 후 재도전','failure','시간0 또는보스중도포기','보스 도전 실패 / 보상0|남은 HP2,100 / 12,000 / 실측DPS206.3|시간 차감12초 / 예약 보너스 미지급',[('일반 사냥','S07'),('특성','S12'),('재도전','S22'),('Main','S04')],'실패사유: 시간초과/포기. 성장안내는공격력·다중타격·자동속도중구매가능한노드를보여주되강제하지않음.','보유재화를차감하지않고보스기본·예약보상만0. 남은HP가0이라면성공과실패가동시에열리지않게보장.')
add(31,'v5 격파 · 엔딩 진입','ending','v5최초처치정산저장성공','고대 드래곤을 쓰러뜨렸습니다|첫 엔딩까지 01:59:40 / 총 처치42,810|드래곤·브레스·추가 성장이 열렸습니다',[('엔딩 보기','S32'),('연출 건너뛰기','S33')],'엔딩플래그와최초시간을저장한뒤20초내외평원회복연출. 시간은메뉴포함·정지제외.','닫거나강제종료해도클리어유지. 다음실행Main에서엔딩다시보기가능, 재처치는최초기록을덮어쓰지않음.')
add(32,'엔딩 · 크레딧','credits','S31엔딩보기 또는Main다시보기','CURSOR HUNTER|평원에 다시 고요가 돌아왔습니다|제작 / 음악 / 사용 에셋 / 감사합니다',[('Main으로','S33')],'20초이내연출과크레딧. ESC/Space새입력으로건너뛰기. 음악페이드와환경복귀.','크레딧실명·에셋표기는실제제작물등록후확정. 허구제작진·라이선스정보를미리기입하지않는다.')
add(33,'엔딩 이후 Main · 자유 성장','main-end','크레딧종료 또는엔딩저장있는재실행','엔딩 완료 / 첫 클리어01:59:40|일반 드래곤 / 드래곤 브레스 / L30 성장|원하는 가지를 더 성장시키세요',[('후반 사냥','S08'),('특성','S12'),('보스 반복','S20'),('기록','S42'),('엔딩 다시 보기','S32')],'추가성장은선택. 엔딩다시보기·보스반복·전체노드완성가능. 초기화는설정의분리된확인에서만.','최초2시간목표와전체완성시간은구분. 끝없는적HP자동상승이나추가필수보스는없다.')
add(34,'설정 · 오디오','settings-audio','Main/일시정지에서설정','전체80% / 음악60% / 효과음80%|구매·타격 소리 미리듣기|오디오 / 화면 / 조작·가독성 / 데이터',[('화면','S35'),('조작·가독성','S37'),('데이터','S38'),('적용','S04'),('변경 취소 확인','S46')],'변경즉시미리듣기·적용때저장. 배경음복귀시중복재생하지않는다. 일시정지에서왔다면적용후S09복귀.','음량0에서도파훼·타이머시각정보유지. ESC시미적용변경있으면S46,없으면진입화면복귀.')
add(35,'설정 · 화면 / 성능','settings-video','설정화면탭','창 / 전체화면 / 테두리 없는 창|해상도1920x1080 / UI100% / FPS60|이펙트 낮음·보통·높음 / 화면 흔들림OFF',[('해상도 적용','S36'),('조작·가독성','S37'),('오디오','S34'),('돌아가기','S46')],'16:9전투영역보존,다른비율레터박스. UI100~150%에서스크롤사용. 전투판정은UI배율과무관.','장치별표시설정은Cloud동기화제외. 지원 해상도 목록은 현재 표시 장치가 제공하는 값으로 구성한다.')
add(36,'표시 변경 확인 · 자동 복원','modal','S35해상도/전체화면변경','이 화면 설정을 유지할까요?|10초 내 확인하지 않으면 이전 설정으로 돌아갑니다|남은 시간 08초',[('유지','S35'),('이전 설정 복원','S35')],'카운트다운은전투일시정지와독립실시간.10초만료·포커스상실시복원.','확인실패시이전해상도로기동할수있게변경전값보존. 검은화면일때도ESC복원가능.')
add(37,'설정 · 입력 / 가독성','settings-input','설정조작·가독성탭','자동 전환 A / 일시정지 ESC / 다음 사냥 Space|트리 이동: 빈 공간 드래그 / 확대: 휠|숫자 묶음 ON / 색상+아이콘 / UI언어',[('키 변경 예시','S47'),('연습 다시 보기','S05'),('데이터','S38'),('적용','S04')],'자동전환키는재지정가능. ESC·공격좌클릭은예약키. Space는정산에서만새입력으로다음일반.','기본홀드공격을추가하지않는다. 자동화는특성해금유지. 게임중연습선택은비활성,정산후가능.')
add(38,'설정 · 언어 / 저장 / 정보','settings-data','설정데이터탭','언어 한국어 / English|로컬 저장:09/09 10:20 / Steam 연결 상태|v0.0.4 / 크레딧 / 새로 시작',[('초기화 확인','S39'),('저장 복구','S03'),('크레딧','S32'),('오디오','S34')],'진행1슬롯,백업3세대,언어는언제든변경. 저장시각과Steam연결을분리하고로컬성공을Cloud성공으로표시하지않는다.','초기화는비전투에서만. Steam 도전과제는 초기화하지 않으며 사용중OS해상도는장치별로유지한다.')
add(39,'새로 시작 · 진행 초기화 재확인','modal','설정데이터에서새로시작','현재 게임 진행을 초기화할까요?|보석·특성·보스·엔딩 기록이 초기화됩니다|Steam 도전과제와 개인 설정은 유지됩니다',[('취소','S38'),('RESET 입력 후 초기화','S02')],'RESET입력+확인2단계,버튼기본비활성. 입력일치후새저장생성,이전진행은복구용백업으로보존.','저장 실패면 기존 진행을 유지한다. 초기화 뒤에는 새 저장을 만들고 백업을 통해 이전 진행을 되돌릴 수 있다.')
add(40,'저장 실패 · 구매 / 정산','modal','구매·정산·설정저장실패','저장하지 못했습니다|오류: 쓰기 실패 / 현재 기록은 메모리에 보관 중|재시도 전까지 구매와 다음 사냥을 잠급니다',[('다시 저장','S45'),('이전 화면 유지','S12'),('종료 확인','S41')],'구매실패는차감·강화롤백,정산실패는결과보관. 재시도는같은ID로처리. 오류코드와사용자읽기용설명을분리.','유지는잠긴기존화면으로만복귀하며플레이를열지않는다. 종료전저장되지않은범위를명확히표시.')
add(41,'게임 종료 확인','modal','Main종료·OS창닫기·저장오류종료','게임을 종료할까요?|저장 완료:09/09 10:20|저장 오류가 있으면 미저장 내역을 여기에 표시',[('취소','S04'),('저장 후 종료','END')],'정상시진행저장후프로세스종료. 런중OS닫기는일반처치정산/보스포기정책을적용하고한번만저장.','저장 실패 시 S40으로 이동하고 저장하지 않고 종료하는 선택을 별도로 제공한다.')
add(42,'기록 · 도전과제','records','Main기록버튼 또는특성요약의전체기록','누적 플레이01:12:20 / 총 처치18,430|보스 최고 기록 / 일반 분당 처치 / 첫 엔딩|도전과제 5 / 12 · 미달성 조건도 표시',[('Main','S04'),('특성 요약','S15'),('보스 선택','S20')],'도전과제12개 조건과 누적 기록을 표시한다. 달성토스트는전투를가리지않는하단우측2초. 오프라인은로컬큐저장.','재접속시중복없이Steam전달. 도전과제API실패가보상·저장·엔딩을막지않음. 외부분석송신은없음.')
add(43,'Steam 미연결 · 로컬 진행 안내','modal','S01 Steam연결불가/오프라인','Steam에 연결되지 않았습니다|로컬 저장으로 계속 플레이할 수 있습니다|Cloud 동기화와 실적 전송은 재연결 후 진행',[('로컬로 계속','S04'),('연결 다시 확인','S01'),('종료','S41')],'장치에유효로컬저장이있으면계속,없으면첫설정. Steam클라이언트충돌선택은클라이언트에서처리한다.','게임이Cloud충돌파일을자동병합하거나최근시각만으로덮어쓰지않는다. 실제연결상태를모를때동기화완료문구금지.')
add(44,'비정상 종료 복구 · 런 정산','modal','S01미완료런저장 또는S03백업복구','이전 사냥이 정상 종료되지 않았습니다|일반: 마지막 체크포인트 보상 회수|보스: 미완료 도전 보상 없음',[('확인 후 Main','S04'),('기록 확인','S42')],'런종류·복구보상·체크포인트시각을표시. 일반최대5초손실가능,보스런재개없음. 동일복구ID한번지급.','이미정산된런이면복구팝업없이최근정산유지. 백업복구는읽은저장의실제내용만표시.')
add(45,'저장 중 · 중복 입력 차단','saving','정산/구매/설정/복구를확정하는순간','저장 중...|획득량과 진행 기록을 안전하게 기록하고 있습니다|완료되면 이동 버튼이 활성화됩니다',[('일반 저장 성공','S11'),('구매 저장 성공','S19'),('보스 저장 성공','S28'),('저장 실패','S40')],'자동상태로대부분짧게지나감. 0.3초이상일때스피너. 저장이 끝날 때까지 화면 전환 버튼을 비활성화한다.','부모작업과결과ID를보존. 타이머가다시흐르지않고화면전환2번발생하지않도록직렬화.')
add(46,'설정 미적용 · 저장 / 버리기','modal','설정변경후ESC/돌아가기','변경한 설정을 적용할까요?|적용하면 저장하고 이전 화면으로 돌아갑니다|버리면 변경 전 값으로 복원합니다',[('적용','S04'),('변경 버리기','S04'),('계속 설정','S34')],'복귀대상은Main/일시정지등진입컨텍스트. 화면확인중이면해상도확인을먼저끝낸다.','미리듣기음량·언어·표시설정이취소후잔존하지않게변경전스냅샷보관. 실패는S40.')
add(47,'키 지정 · 중복 / 예약 키','modal','자동전환단축키변경','새 키를 눌러 주세요|ESC는 일시정지 예약 키입니다|다른 키를 선택하거나 기본값 A로 복원하세요',[('A로 복원','S37'),('취소','S37')],'변경중입력은전투/트리단축키로전달하지않는다. 예약키·중복키는적용비활성,충돌기능명표시.','정의되지않은마우스버튼을임의지원하지않음. 포커스상실시취소. 캡처리스너는닫힐때해제.')
